# syntax=docker/dockerfile:1.7
#
# Postiz on ECS, one slim image per app, built from a checkout of
# gitroomhq/postiz-app. postiz-app itself is not changed: its all-in-one image
# stays the easy path for self-hosters.
#
#   --target frontend      Next standalone server (enabled by a config wrapper below)
#   --target backend       backend build + only the files main.js loads; also runs mcp
#   --target orchestrator  orchestrator build + only the files main.js loads (workers)
#   --target migrate       Prisma CLI + schema.prisma, for the db push task
#
# The apps declare no dependencies of their own (postiz-app keeps all 270 in the
# root package.json), so pnpm cannot prune per app: the backend and orchestrator
# images keep what @vercel/nft traces from their entrypoint, plus the generated
# Prisma client, whose query engine is loaded by a computed path.
# Node and pnpm versions follow postiz-app's package.json (engines, packageManager).

ARG NODE_IMAGE=node:22.23.4-bookworm-slim

# --- dependencies, shared by the app builds -------------------------------------------
FROM ${NODE_IMAGE} AS deps
RUN apt-get update \
 && apt-get install -y --no-install-recommends g++ make python3 ca-certificates openssl libudev-dev \
 && rm -rf /var/lib/apt/lists/* \
 && npm --no-update-notifier --no-fund --global install pnpm@10.6.1
WORKDIR /app
# Plain install, as on Railway: the root postinstall runs `pnpm dlx prisma generate`,
# which needs the network.
COPY . /app
RUN pnpm install --frozen-lockfile

# --- frontend ---------------------------------------------------------------------------
FROM deps AS frontend-build
# Standalone output without touching postiz-app's next.config.js: wrap it. The
# tracing root is the monorepo, so libraries/* and the hoisted packages are included.
RUN mv apps/frontend/next.config.js apps/frontend/next.config.postiz.js
COPY <<'EOF' /app/apps/frontend/next.config.js
import { fileURLToPath } from 'node:url';
import postiz from './next.config.postiz.js';

const aws = {
  output: 'standalone',
  outputFileTracingRoot: fileURLToPath(new URL('../../', import.meta.url)),
};

export default typeof postiz === 'function'
  ? async (...args) => ({ ...(await postiz(...args)), ...aws })
  : { ...postiz, ...aws };
EOF
# NEXT_PUBLIC_* values are compiled into the browser bundle: they come in as a
# BuildKit secret file of KEY='value' lines and never land in an image layer.
RUN --mount=type=secret,id=frontend_env,required=false \
    set -a \
 && if [ -f /run/secrets/frontend_env ]; then . /run/secrets/frontend_env; fi \
 && set +a \
 && NODE_OPTIONS="--max-old-space-size=6144" pnpm --filter ./apps/frontend run build

FROM ${NODE_IMAGE} AS frontend
WORKDIR /app
COPY --from=frontend-build /app/apps/frontend/.next/standalone ./
COPY --from=frontend-build /app/apps/frontend/.next/static ./apps/frontend/.next/static
COPY --from=frontend-build /app/apps/frontend/public ./apps/frontend/public
ENV NODE_ENV=production PORT=4200 HOSTNAME=0.0.0.0
WORKDIR /app/apps/frontend
CMD ["node", "server.js"]

# --- tracing for the Nest apps -----------------------------------------------------------
FROM deps AS trace
RUN npm --no-update-notifier --no-fund install --prefix /trace @vercel/nft@1.11.0
# Copies what the entrypoints load (comma-separated), plus whole extra
# directories, into OUT with /app's layout and any symlinks intact. Prints the
# tracer's warnings (loads it could not resolve) so a build log shows them.
COPY <<'EOF' /trace/trace.mjs
import { nodeFileTrace } from '@vercel/nft';
import { copyFile, lstat, mkdir, readdir, readFile, readlink, symlink } from 'node:fs/promises';
import { dirname, join, relative } from 'node:path';

const [entries, out, cwd, ...extra] = process.argv.slice(2);
const entry = entries.split(',');
const base = '/app';
const { fileList, warnings } = await nodeFileTrace(entry, { base, processCwd: cwd, mixedModules: true });
const files = new Set(fileList);
for (const w of warnings) console.log(`trace warning: ${String(w.message || w).split('\n')[0]}`);

async function walk(dir) {
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) await walk(p);
    else files.add(relative(base, p));
  }
}
// extra: directories to copy whole, or @file with one absolute path per line
// (only its files: webpack also lists directories it watched, like node_modules)
for (const x of extra) {
  if (x.startsWith('@')) {
    for (const p of (await readFile(x.slice(1), 'utf8')).split('\n')) {
      if (!p.startsWith(base + '/')) continue;
      const st = await lstat(p).catch(() => null);
      if (st && !st.isDirectory()) files.add(relative(base, p));
    }
  } else {
    await walk(join(base, x));
  }
}

let links = 0;
for (const f of files) {
  const src = join(base, f);
  const dst = join(out, f);
  await mkdir(dirname(dst), { recursive: true });
  const st = await lstat(src);
  if (st.isSymbolicLink()) {
    links++;
    await symlink(await readlink(src), dst).catch((e) => { if (e.code !== 'EEXIST') throw e; });
  } else if (st.isFile()) {
    await copyFile(src, dst);
  }
}
console.log(`traced ${entry}: ${files.size} files (${links} symlinks), ${warnings.size} warnings`);
EOF
# Bundles the workflows exactly as the workers' Temporal SDK does at startup and
# prints every file webpack read: the workflow bundle resolves packages through
# their ESM entries, which a require() trace does not follow.
COPY <<'EOF' /trace/workflow-files.mjs
import { createRequire } from 'node:module';
import { join, resolve } from 'node:path';

const require = createRequire(join(process.cwd(), 'package.json'));
const { bundleWorkflowCode } = require('@temporalio/worker');
const files = new Set();
await bundleWorkflowCode({
  workflowsPath: resolve(process.argv[2]),
  logger: { trace() {}, debug() {}, info() {}, warn() {}, error: (m) => console.error(m) },
  webpackConfigHook: (config) => {
    config.plugins = [...(config.plugins || []), {
      apply: (compiler) => compiler.hooks.done.tap('workflow-files', (stats) => {
        if (stats.hasErrors()) throw new Error(stats.toString({ errorDetails: false, all: false, errors: true }));
        for (const f of stats.compilation.fileDependencies) files.add(f);
      }),
    }];
    return config;
  },
});
console.log([...files].join('\n'));
EOF

# node_modules is hoisted (postiz-app's .npmrc: node-linker=hoisted), so the
# generated Prisma client and its query engine live in node_modules/.prisma.
FROM trace AS backend-build
RUN NODE_OPTIONS="--max-old-space-size=6144" pnpm --filter ./apps/backend run build \
 && node /trace/trace.mjs apps/backend/dist/apps/backend/src/main.js /out /app/apps/backend \
      node_modules/.prisma

# The workers' Temporal SDK bundles the workflow code with webpack when it starts,
# reading those files from disk rather than requiring them: add every file that
# bundling reads (workflow-files.mjs), or tslib, @temporalio/workflow, ... are missing.
FROM trace AS orchestrator-build
RUN NODE_OPTIONS="--max-old-space-size=6144" pnpm --filter ./apps/orchestrator run build \
 && (cd apps/orchestrator && node /trace/workflow-files.mjs ./dist/apps/orchestrator/src/workflows > /tmp/workflow-files.txt) \
 && echo "workflow bundle reads $(wc -l < /tmp/workflow-files.txt) files" \
 && node /trace/trace.mjs \
      apps/orchestrator/dist/apps/orchestrator/src/main.js,apps/orchestrator/dist/apps/orchestrator/src/workflows/index.js \
      /out /app/apps/orchestrator node_modules/.prisma @/tmp/workflow-files.txt

# --- runtime for the Nest apps (openssl: Prisma's engine; libudev1: native HID modules) --
FROM ${NODE_IMAGE} AS nest-runtime
RUN apt-get update \
 && apt-get install -y --no-install-recommends ca-certificates openssl libudev1 \
 && rm -rf /var/lib/apt/lists/*
ENV NODE_ENV=production

FROM nest-runtime AS backend
COPY --from=backend-build /out /app
WORKDIR /app/apps/backend
CMD ["node", "--experimental-require-module", "./dist/apps/backend/src/main.js"]

FROM nest-runtime AS orchestrator
COPY --from=orchestrator-build /out /app
WORKDIR /app/apps/orchestrator
CMD ["node", "--experimental-require-module", "./dist/apps/orchestrator/src/main.js"]

# --- prisma db push (the Railway pre-deploy command) --------------------------------------
FROM ${NODE_IMAGE} AS migrate
RUN apt-get update \
 && apt-get install -y --no-install-recommends ca-certificates openssl \
 && rm -rf /var/lib/apt/lists/* \
 && npm --no-update-notifier --no-fund --global install prisma@6.5.0
WORKDIR /app
COPY libraries/nestjs-libraries/src/database/prisma/schema.prisma ./schema.prisma
# --skip-generate: no client to generate here; the app images carry their own.
CMD ["prisma", "db", "push", "--schema", "./schema.prisma", "--skip-generate"]

variable "aws_account_id" {
  description = "The only AWS account these stacks may touch (TF_VAR_aws_account_id)."
  type        = string
}

variable "region" {
  description = "Home region."
  type        = string
  default     = "us-east-2"
}

variable "github_repository" {
  description = "owner/name of the GitHub repository holding this code."
  type        = string
  default     = "gitroomhq/postiz-aws"
}

variable "github_oidc_subject" {
  description = <<-EOT
    Start of the sub claim in this repository's GitHub OIDC tokens, printed by
    gh api repos/OWNER/NAME/actions/oidc/customization/sub --jq .sub_claim_prefix
    Repositories created since July 2026 carry the owner and repository ids
    (repo:owner@id/name@id), older ones repo:owner/name.
  EOT
  type        = string
  default     = "repo:gitroomhq@128401275/postiz-aws@1436140501"

  validation {
    condition     = can(regex("^repo:[^:]+$", var.github_oidc_subject))
    error_message = "Only the prefix, for example repo:owner@123/name@456 (no :ref: or :environment: part)."
  }
}

# One-time account setup, applied by hand with admin credentials:
#   export AWS_PROFILE=<profile> TF_VAR_aws_account_id=<your account id>
#   terraform -chdir=bootstrap init && terraform -chdir=bootstrap apply
#
# Creates what every other stack needs before it can run in CI:
#   - the S3 bucket holding Terraform state (native S3 locking, no DynamoDB)
#   - the GitHub OIDC provider
#   - postiz-github-terraform-plan   read-only, used by pull requests (plans run with
#                                    -refresh=false, so it never needs a secret value; any
#                                    branch can change the workflow, so it must stay weak)
#   - postiz-github-terraform-apply  admin, only from the "production" GitHub environment
#   - postiz-agent-readonly          for AI agents and humans poking around, cannot read secret values
#   - postiz-team-readonly           for team members signing in through IAM Identity Center
#                                    (account access manager), cannot read secret values

terraform {
  required_version = ">= 1.11.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.70, < 7.0"
    }
  }

  # After the first apply, move this stack's own state into the bucket it created:
  #   uncomment, then: terraform -chdir=bootstrap init -migrate-state -backend-config=../environments/production/backend.hcl
  # backend "s3" {
  #   key          = "bootstrap/terraform.tfstate"
  #   region       = "us-east-2"
  #   use_lockfile = true
  #   encrypt      = true
  # }
}

provider "aws" {
  region              = var.region
  allowed_account_ids = [var.aws_account_id]

  default_tags {
    tags = {
      Project   = "postiz"
      ManagedBy = "terraform"
      Stack     = "bootstrap"
    }
  }
}

locals {
  state_bucket = "postiz-terraform-state-${var.aws_account_id}"
  github_sub   = var.github_oidc_subject
}

# ---------------------------------------------------------------------------
# Terraform state bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"
    filter {}
    noncurrent_version_expiration {
      noncurrent_days = 90
    }
    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}

# ---------------------------------------------------------------------------
# GitHub Actions OIDC
# ---------------------------------------------------------------------------

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "state_read" {
  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.state.arn]
  }
  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.state.arn}/*"]
  }
}

data "aws_iam_policy_document" "state_lock" {
  # terraform plan takes the lock too, so even the read-only plan role writes .tflock files
  statement {
    sid       = "ManageLockFiles"
    actions   = ["s3:PutObject", "s3:DeleteObject"]
    resources = ["${aws_s3_bucket.state.arn}/*.tflock"]
  }
}

# --- plan role: pull requests and main, read-only ---------------------------

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values = [
        "${local.github_sub}:pull_request",
        "${local.github_sub}:ref:refs/heads/main",
      ]
    }
  }
}

resource "aws_iam_role" "plan" {
  name                 = "postiz-github-terraform-plan"
  description          = "GitHub Actions terraform plan for ${var.github_repository} (read-only)"
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy_attachment" "plan_readonly" {
  role       = aws_iam_role.plan.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

data "aws_iam_policy_document" "plan_extra" {
  source_policy_documents = [
    data.aws_iam_policy_document.state_read.json,
    data.aws_iam_policy_document.state_lock.json,
  ]
}

resource "aws_iam_role_policy" "plan_extra" {
  name   = "terraform-state-and-refresh"
  role   = aws_iam_role.plan.id
  policy = data.aws_iam_policy_document.plan_extra.json
}

# --- apply role: only jobs running in the protected "production" environment ---

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["${local.github_sub}:environment:production"]
    }
  }
}

resource "aws_iam_role" "apply" {
  name                 = "postiz-github-terraform-apply"
  description          = "GitHub Actions terraform apply for ${var.github_repository}, production environment only"
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 7200 # a first apply (RDS Multi-AZ, CloudFront) can pass an hour
}

# Terraform creates IAM roles, so a narrower policy would still be admin-equivalent.
# The guard is the trust policy: only reviewed jobs in the production environment.
resource "aws_iam_role_policy_attachment" "apply_admin" {
  role       = aws_iam_role.apply.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# --- read-only role for AI agents and humans --------------------------------

data "aws_iam_policy_document" "agent_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.aws_account_id}:root"]
    }
  }
}

resource "aws_iam_role" "agent_readonly" {
  name                 = "postiz-agent-readonly"
  description          = "Read-only access for AI agents, no secret values"
  assume_role_policy   = data.aws_iam_policy_document.agent_trust.json
  max_session_duration = 43200
}

resource "aws_iam_role_policy_attachment" "agent_readonly" {
  role       = aws_iam_role.agent_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

data "aws_iam_policy_document" "agent_extra" {
  source_policy_documents = [data.aws_iam_policy_document.state_read.json]

  statement {
    sid    = "NoSecretValues"
    effect = "Deny"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:BatchGetSecretValue",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
      "ecs:ExecuteCommand",
      "ssm:StartSession",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "agent_extra" {
  name   = "state-read-no-secrets"
  role   = aws_iam_role.agent_readonly.id
  policy = data.aws_iam_policy_document.agent_extra.json
}

# --- read-only role for team members ------------------------------------------
# Assigned to IAM Identity Center users through account access manager (an
# entitlement in the management account), the same way AccountFullAccessRole is.
# Members sign in through the account access portal or with `aws login`.

data "aws_iam_policy_document" "team_trust" {
  statement {
    actions = ["sts:AssumeRole", "sts:SetContext"]
    principals {
      type        = "Service"
      identifiers = ["account-access.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "team_readonly" {
  name                 = "postiz-team-readonly"
  description          = "Read-only access for team members via account access manager, no secret values"
  assume_role_policy   = data.aws_iam_policy_document.team_trust.json
  max_session_duration = 43200
}

resource "aws_iam_role_policy_attachment" "team_readonly" {
  role       = aws_iam_role.team_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# Amazon Q Developer chat in the console. Q acts on AWS resources with the
# caller's own permissions (q:PassRequest), so it is still limited to
# ReadOnlyAccess and the NoSecretValues deny below.
resource "aws_iam_role_policy_attachment" "team_readonly_amazon_q" {
  role       = aws_iam_role.team_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonQDeveloperAccess"
}

data "aws_iam_policy_document" "no_secret_values" {
  statement {
    sid    = "NoSecretValues"
    effect = "Deny"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:BatchGetSecretValue",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
      "ecs:ExecuteCommand",
      "ssm:StartSession",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "team_readonly" {
  name   = "no-secret-values"
  role   = aws_iam_role.team_readonly.id
  policy = data.aws_iam_policy_document.no_secret_values.json
}

output "state_bucket" {
  value = aws_s3_bucket.state.bucket
}

output "github_oidc_provider_arn" {
  value = aws_iam_openid_connect_provider.github.arn
}

output "plan_role_arn" {
  description = "GitHub variable AWS_PLAN_ROLE_ARN"
  value       = aws_iam_role.plan.arn
}

output "apply_role_arn" {
  description = "GitHub variable AWS_APPLY_ROLE_ARN"
  value       = aws_iam_role.apply.arn
}

output "agent_readonly_role_arn" {
  description = "Add to ~/.aws/config as a profile whose source_profile is your admin profile"
  value       = aws_iam_role.agent_readonly.arn
}

output "team_readonly_role_arn" {
  description = "Role to grant team members in account access manager (create-entitlement)"
  value       = aws_iam_role.team_readonly.arn
}

# Temporal visibility store (Railway "Elasticsearch", ES 8.19.10).
#
# Why not Postgres visibility or Amazon OpenSearch yet:
#   - Postiz finds a post's running workflow with
#     workflow.list('postId="..." AND ExecutionStatus="Running"') before deleting
#     or re-scheduling it (posts.service.ts deletePost / startWorkflow).
#   - Switching an existing cluster to SQL visibility leaves already-running
#     workflows unlisted, and `tdbg workflow refresh-tasks` does not rebuild them
#     on 1.28 (tested), so deleted or drafted posts could still publish.
#   - Amazon OpenSearch is only supported from Temporal 1.30.1.
# So the index moves as-is (scripts/es-copy-index.py) onto one EC2 host with a
# separate EBS data volume and daily snapshots.

data "aws_ssm_parameter" "al2023_arm64" {
  name = "/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-arm64"
}

ephemeral "random_password" "elasticsearch" {
  length  = 40
  special = false
}

locals {
  es_az = module.network.azs[0]
}

resource "aws_secretsmanager_secret" "elasticsearch" {
  name        = "${local.secret_prefix}/managed/elasticsearch"
  description = "Elasticsearch elastic user, written by Terraform"
}

resource "aws_secretsmanager_secret_version" "elasticsearch" {
  secret_id = aws_secretsmanager_secret.elasticsearch.id
  secret_string_wo = jsonencode({
    username = "elastic"
    password = [REDACTED]
    url      = "http://elastic:${ephemeral.random_password.elasticsearch.result}@${local.elasticsearch_host}:9200"
  })
  secret_string_wo_version = var.elasticsearch_password_version
}

resource "aws_cloudwatch_log_group" "elasticsearch" {
  name              = "/ec2/${local.name}/elasticsearch"
  retention_in_days = var.log_retention_days
}

resource "aws_security_group" "elasticsearch" {
  name        = "${local.name}-elasticsearch"
  description = "Elasticsearch for Temporal visibility"
  vpc_id      = module.network.vpc_id
  tags        = { Name = "${local.name}-elasticsearch" }
}

resource "aws_vpc_security_group_ingress_rule" "es_from_temporal" {
  security_group_id            = aws_security_group.elasticsearch.id
  referenced_security_group_id = aws_security_group.temporal.id
  ip_protocol                  = "tcp"
  from_port                    = 9200
  to_port                      = 9200
  description                  = "Temporal visibility"
}

resource "aws_vpc_security_group_ingress_rule" "es_from_ops" {
  security_group_id            = aws_security_group.elasticsearch.id
  referenced_security_group_id = module.ecs_cluster.instance_security_group_id
  ip_protocol                  = "tcp"
  from_port                    = 9200
  to_port                      = 9200
  description                  = "Migration toolbox copying the Railway index"
}

resource "aws_vpc_security_group_egress_rule" "es_all" {
  security_group_id = aws_security_group.elasticsearch.id
  ip_protocol       = "-1"
  cidr_ipv4         = "0.0.0.0/0"
  description       = "Image pulls, OS updates, Secrets Manager, CloudWatch, SSM"
}

# --- host IAM -------------------------------------------------------------------------

data "aws_iam_policy_document" "es_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "elasticsearch" {
  name               = "${local.name}-elasticsearch"
  description        = "Elasticsearch host of ${local.name}"
  assume_role_policy = data.aws_iam_policy_document.es_trust.json
}

resource "aws_iam_role_policy_attachment" "es_ssm" {
  role       = aws_iam_role.elasticsearch.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "es_host" {
  statement {
    sid       = "ReadOwnPassword"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.elasticsearch.arn]
  }
  statement {
    sid       = "ContainerLogs"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
    resources = ["${aws_cloudwatch_log_group.elasticsearch.arn}:*"]
  }
}

resource "aws_iam_role_policy" "es_host" {
  name   = "elasticsearch-host"
  role   = aws_iam_role.elasticsearch.id
  policy = data.aws_iam_policy_document.es_host.json
}

resource "aws_iam_instance_profile" "elasticsearch" {
  name = "${local.name}-elasticsearch"
  role = aws_iam_role.elasticsearch.name
}

# --- host + data volume ---------------------------------------------------------------

resource "aws_ebs_volume" "elasticsearch" {
  availability_zone = local.es_az
  size              = var.elasticsearch_volume_size
  type              = "gp3"
  encrypted         = true

  tags = {
    Name     = "${local.name}-elasticsearch-data"
    Snapshot = "${local.name}-elasticsearch"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_instance" "elasticsearch" {
  ami                         = data.aws_ssm_parameter.al2023_arm64.insecure_value
  instance_type               = var.elasticsearch_instance_type
  subnet_id                   = module.network.public_subnet_ids_by_az[local.es_az]
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.elasticsearch.id]
  iam_instance_profile        = aws_iam_instance_profile.elasticsearch.name
  disable_api_termination     = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  maintenance_options {
    auto_recovery = "default"
  }

  root_block_device {
    volume_type = "gp3"
    volume_size = 20
    encrypted   = true
  }

  user_data = templatefile("${path.module}/elasticsearch-user-data.sh.tftpl", {
    region         = var.region
    volume_id      = aws_ebs_volume.elasticsearch.id
    secret_arn     = aws_secretsmanager_secret.elasticsearch.arn
    log_group      = aws_cloudwatch_log_group.elasticsearch.name
    es_version     = var.elasticsearch_version
    es_heap        = var.elasticsearch_heap
    secret_version = var.elasticsearch_password_version
    # referenced so the password exists before the host first boots and reads it
    secret_resource = aws_secretsmanager_secret_version.elasticsearch.id
  })

  tags = { Name = "${local.name}-elasticsearch" }

  lifecycle {
    # a newer AMI or edited boot script must not silently replace the host;
    # replace it on purpose with: terraform apply -replace=aws_instance.elasticsearch
    ignore_changes = [ami, user_data]
  }
}

resource "aws_volume_attachment" "elasticsearch" {
  device_name                    = "/dev/sdf"
  volume_id                      = aws_ebs_volume.elasticsearch.id
  instance_id                    = aws_instance.elasticsearch.id
  stop_instance_before_detaching = true
}

# elasticsearch.postiz.internal -> host private IP
resource "aws_service_discovery_service" "elasticsearch" {
  name = "elasticsearch"

  dns_config {
    namespace_id   = aws_service_discovery_private_dns_namespace.internal.id
    routing_policy = "MULTIVALUE"
    dns_records {
      type = "A"
      ttl  = 60
    }
  }
}

resource "aws_service_discovery_instance" "elasticsearch" {
  instance_id = "elasticsearch-1"
  service_id  = aws_service_discovery_service.elasticsearch.id
  attributes = {
    AWS_INSTANCE_IPV4 = aws_instance.elasticsearch.private_ip
  }
}

# --- daily snapshots of the data volume, 7 kept ------------------------------------------

data "aws_iam_policy_document" "dlm_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["dlm.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [var.aws_account_id]
    }
  }
}

resource "aws_iam_role" "dlm" {
  name               = "${local.name}-dlm"
  description        = "Data Lifecycle Manager snapshots for ${local.name}"
  assume_role_policy = data.aws_iam_policy_document.dlm_trust.json
}

resource "aws_iam_role_policy_attachment" "dlm" {
  role       = aws_iam_role.dlm.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSDataLifecycleManagerServiceRole"
}

resource "aws_dlm_lifecycle_policy" "elasticsearch" {
  description        = "Daily snapshots of the Elasticsearch data volume"
  execution_role_arn = aws_iam_role.dlm.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]
    target_tags = {
      Snapshot = "${local.name}-elasticsearch"
    }

    schedule {
      name      = "daily"
      copy_tags = true

      create_rule {
        interval      = 24
        interval_unit = "HOURS"
        times         = ["05:00"]
      }

      retain_rule {
        count = 7
      }
    }
  }
}

# Role for .github/workflows/deploy.yml and ops-image.yml: build and push the
# images, run prisma db push, roll the services. Only jobs in the "deploy" GitHub
# environment can assume it: main branch only, no reviewers, so a push to the
# app deploys on its own like on Railway (terraform apply keeps "production").

data "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
}

data "aws_iam_policy_document" "deploy_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [data.aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["${var.github_oidc_subject}:environment:deploy"]
    }
  }
}

resource "aws_iam_role" "deploy" {
  name                 = "${local.name}-github-deploy"
  description          = "GitHub Actions deploys of Postiz to ${local.name}"
  assume_role_policy   = data.aws_iam_policy_document.deploy_trust.json
  max_session_duration = 7200
}

locals {
  cluster_arn_prefix = "arn:aws:ecs:${var.region}:${var.aws_account_id}"
}

data "aws_iam_policy_document" "deploy" {
  statement {
    sid       = "EcrLogin"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid = "PushImages"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeImages",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart",
    ]
    resources = [aws_ecr_repository.app.arn, aws_ecr_repository.ops.arn]
  }

  statement {
    sid       = "RollServices"
    actions   = ["ecs:UpdateService", "ecs:DescribeServices"]
    resources = ["${local.cluster_arn_prefix}:service/${module.ecs_cluster.cluster_name}/*"]
  }

  statement {
    sid       = "RunDbPush"
    actions   = ["ecs:RunTask"]
    resources = ["${local.cluster_arn_prefix}:task-definition/${module.db_push.task_definition_family}:*"]
    condition {
      test     = "ArnEquals"
      variable = "ecs:cluster"
      values   = [module.ecs_cluster.cluster_arn]
    }
  }

  statement {
    sid       = "WatchTasks"
    actions   = ["ecs:DescribeTasks"]
    resources = ["${local.cluster_arn_prefix}:task/${module.ecs_cluster.cluster_name}/*"]
  }

  statement {
    sid       = "FindRunningDbPush"
    actions   = ["ecs:ListTasks"]
    resources = ["*"]
    condition {
      test     = "ArnEquals"
      variable = "ecs:cluster"
      values   = [module.ecs_cluster.cluster_arn]
    }
  }

  statement {
    sid       = "ReadTaskDefinitions"
    actions   = ["ecs:DescribeTaskDefinition"]
    resources = ["*"]
  }

  statement {
    sid       = "PassDbPushRoles"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.execution.arn, module.db_push.task_role_arn]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }

  statement {
    sid       = "ReadDbPushLogs"
    actions   = ["logs:GetLogEvents", "logs:FilterLogEvents"]
    resources = ["${module.db_push.log_group_arn}:*"]
  }

  # The build only keeps the NEXT_PUBLIC_* keys (they end up in the browser bundle).
  statement {
    sid       = "ReadFrontendBuildValues"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.app["frontend"].arn]
  }
}

resource "aws_iam_role_policy" "deploy" {
  name   = "deploy"
  role   = aws_iam_role.deploy.id
  policy = data.aws_iam_policy_document.deploy.json
}

